/// Mirrors the API type of the same name, laid out to match the wire.
#[derive(Clone, Debug, Default)]
pub struct CustomTooltipField {
    pub name: Value,
    pub value: Value,
    pub quality_header: LuaStr,
    pub quality_values: BTreeMap<LuaStr, Value>,
    pub order: u8,
    pub show_in_factoriopedia: bool,
    pub show_in_tooltip: bool,
}

impl CustomTooltipField {
    pub fn encode_at(&self, d: &mut [u8]) {
        for b in d[..56].iter_mut() { *b = 0; }
        write_dyn(&mut d[0..], &self.name);
        write_dyn(&mut d[16..], &self.value);
        put_str(&mut d[..], 32, self.quality_header.as_bytes());
        let p = galloc((self.quality_values.len() * 24) as u32);
        for (i, (k, v)) in self.quality_values.iter().enumerate() {
            let s = unsafe { core::slice::from_raw_parts_mut((p as usize + i * 24) as *mut u8, 24) };
            put_str(&mut s[..], 0, k.as_bytes());
            write_dyn(&mut s[8..], v);
        }
        wr_u32(&mut d[..], 40, p);
        wr_u32(&mut d[..], 44, self.quality_values.len() as u32);
        d[48..49].copy_from_slice(&(self.order as u8).to_le_bytes());
        d[49] = if self.show_in_factoriopedia { 1 } else { 0 };
        d[50] = if self.show_in_tooltip { 1 } else { 0 };
    }

    pub fn decode_at(d: &[u8]) -> Self {
        let mut v = Self::default();
        v.name = read_dyn(&d[0..]);
        v.value = read_dyn(&d[16..]);
        v.quality_header = get_str(&d[..], 32);
        {
            let base = rd_u32(&d[..], 40) as usize;
            let n = rd_u32(&d[..], 44) as usize;
            for i in 0..n {
                let s = unsafe { core::slice::from_raw_parts((base + i * 24) as *const u8, 24) };
                v.quality_values.insert(get_str(&s[..], 0), read_dyn(&s[8..]));
            }
        }
        v.order = u8::from_le_bytes(d[48..49].try_into().unwrap());
        v.show_in_factoriopedia = d[49] != 0;
        v.show_in_tooltip = d[50] != 0;
        v
    }

    /// Renders this as the tier-2 table the engine expects, so a
    /// union-typed field can be filled from the typed struct instead of
    /// from hand-written key strings. An absent optional is omitted.
    pub fn to_value(&self) -> Value {
        let mut kv: Vec<(Value, Value)> = Vec::with_capacity(7);
        kv.push((Value::Str(LuaStr::from("name")), self.name.clone()));
        kv.push((Value::Str(LuaStr::from("value")), self.value.clone()));
        kv.push((Value::Str(LuaStr::from("quality_header")), Value::Str(self.quality_header.clone())));
        if !self.quality_values.is_empty() {
            let mut m: Vec<(Value, Value)> = Vec::new();
            for (k, v) in self.quality_values.iter() {
                m.push((Value::Str(k.clone()), v.clone()));
            }
            kv.push((Value::Str(LuaStr::from("quality_values")), Value::Map(m)));
        }
        kv.push((Value::Str(LuaStr::from("order")), Value::Number(self.order as f64)));
        kv.push((Value::Str(LuaStr::from("show_in_factoriopedia")), Value::Bool(self.show_in_factoriopedia)));
        kv.push((Value::Str(LuaStr::from("show_in_tooltip")), Value::Bool(self.show_in_tooltip)));
        Value::Map(kv)
    }
}

