#[derive(Clone, Debug, Default)]
pub struct PrototypeHistory {
    pub created: LuaStr,
    pub changed: Vec<LuaStr>,
}

impl PrototypeHistory {
    pub fn encode_at(&self, d: &mut [u8]) {
        for b in d[..16].iter_mut() { *b = 0; }
        put_str(&mut d[..], 0, self.created.as_bytes());
        let p = galloc((self.changed.len() * 8) as u32);
        for (i, e) in self.changed.iter().enumerate() {
            let s = unsafe { core::slice::from_raw_parts_mut((p as usize + i * 8) as *mut u8, 8) };
            put_str(&mut s[..], 0, e.as_bytes());
        }
        wr_u32(&mut d[..], 8, p);
        wr_u32(&mut d[..], 12, self.changed.len() as u32);
    }

    pub fn decode_at(d: &[u8]) -> Self {
        let mut v = Self::default();
        v.created = get_str(&d[..], 0);
        {
            let base = rd_u32(&d[..], 8) as usize;
            let n = rd_u32(&d[..], 12) as usize;
            for i in 0..n {
                let s = unsafe { core::slice::from_raw_parts((base + i * 8) as *const u8, 8) };
                v.changed.push(get_str(&s[..], 0));
            }
        }
        v
    }

    /// Renders this as the tier-2 table the engine expects, so a
    /// union-typed field can be filled from the typed struct instead of
    /// from hand-written key strings. An absent optional is omitted.
    pub fn to_value(&self) -> Value {
        let mut kv: Vec<(Value, Value)> = Vec::with_capacity(2);
        kv.push((Value::Str(LuaStr::from("created")), Value::Str(self.created.clone())));
        if !self.changed.is_empty() {
            let mut a: Vec<Value> = Vec::with_capacity(self.changed.len());
            for e in self.changed.iter() {
                a.push(Value::Str(e.clone()));
            }
            kv.push((Value::Str(LuaStr::from("changed")), Value::Array(a)));
        }
        Value::Map(kv)
    }
}

