pub struct MapGenPreset {
    pub order: LuaStr,
    pub default: Option<bool>,
    pub basic_settings: Option<MapGenSettings>,
    pub advanced_settings: Option<AdvancedMapGenSettings>,
}

impl MapGenPreset {
    pub fn encode_at(&self, d: &mut [u8]) {
        for b in d[..456].iter_mut() { *b = 0; }
        put_str(&mut d[..], 0, self.order.as_bytes());
        if let Some(v) = &self.default {
            d[8] = 1;
            d[9] = if *v { 1 } else { 0 };
        }
        if let Some(v) = &self.basic_settings {
            d[10] = 1;
            v.encode_at(&mut d[16..]);
        }
        if let Some(v) = &self.advanced_settings {
            d[200] = 1;
            v.encode_at(&mut d[208..]);
        }
    }

    pub fn decode_at(d: &[u8]) -> Self {
        let mut v = Self::default();
        v.order = get_str(&d[..], 0);
        if d[8] != 0 {
            v.default = Some(d[9] != 0);
        }
        if d[10] != 0 {
            v.basic_settings = Some(MapGenSettings::decode_at(&d[16..]));
        }
        if d[200] != 0 {
            v.advanced_settings = Some(AdvancedMapGenSettings::decode_at(&d[208..]));
        }
        v
    }

    /// Renders this as the tier-2 table the engine expects, so a
    /// union-typed field can be filled from the typed struct instead of
    /// from hand-written key strings. An absent optional is omitted.
    pub fn to_value(&self) -> Value {
        let mut kv: Vec<(Value, Value)> = Vec::with_capacity(4);
        kv.push((Value::Str(LuaStr::from("order")), Value::Str(self.order.clone())));
        if let Some(x) = &self.default {
            kv.push((Value::Str(LuaStr::from("default")), Value::Bool(*x)));
        }
        if let Some(x) = &self.basic_settings {
            kv.push((Value::Str(LuaStr::from("basic_settings")), x.to_value()));
        }
        if let Some(x) = &self.advanced_settings {
            kv.push((Value::Str(LuaStr::from("advanced_settings")), x.to_value()));
        }
        Value::Map(kv)
    }
}

