#[derive(Clone, Debug, Default)]
pub struct GhostShimmerConfig {
    pub tint: Color,
    pub distortion: f32,
    pub blend_mode: i32,
    pub visualize_borders: bool,
    pub proportional_distortion: bool,
    pub world_uv_modulo: f32,
    pub overlay_layers: Vec<GhostShimmerOverlayData>,
    pub distortion_layers: Vec<GhostShimmerDistortionData>,
}

impl GhostShimmerConfig {
    pub fn encode_at(&self, d: &mut [u8]) {
        for b in d[..64].iter_mut() { *b = 0; }
        self.tint.encode_at(&mut d[0..]);
        d[32..36].copy_from_slice(&(self.distortion).to_le_bytes());
        d[36..40].copy_from_slice(&(self.blend_mode as i32).to_le_bytes());
        d[40] = if self.visualize_borders { 1 } else { 0 };
        d[41] = if self.proportional_distortion { 1 } else { 0 };
        d[44..48].copy_from_slice(&(self.world_uv_modulo).to_le_bytes());
        let p = galloc((self.overlay_layers.len() * 52) as u32);
        for (i, e) in self.overlay_layers.iter().enumerate() {
            let s = unsafe { core::slice::from_raw_parts_mut((p as usize + i * 52) as *mut u8, 52) };
            e.encode_at(&mut s[0..]);
        }
        wr_u32(&mut d[..], 48, p);
        wr_u32(&mut d[..], 52, self.overlay_layers.len() as u32);
        let p = galloc((self.distortion_layers.len() * 16) as u32);
        for (i, e) in self.distortion_layers.iter().enumerate() {
            let s = unsafe { core::slice::from_raw_parts_mut((p as usize + i * 16) as *mut u8, 16) };
            e.encode_at(&mut s[0..]);
        }
        wr_u32(&mut d[..], 56, p);
        wr_u32(&mut d[..], 60, self.distortion_layers.len() as u32);
    }

    pub fn decode_at(d: &[u8]) -> Self {
        let mut v = Self::default();
        v.tint = Color::decode_at(&d[0..]);
        v.distortion = f32::from_le_bytes(d[32..36].try_into().unwrap());
        v.blend_mode = i32::from_le_bytes(d[36..40].try_into().unwrap());
        v.visualize_borders = d[40] != 0;
        v.proportional_distortion = d[41] != 0;
        v.world_uv_modulo = f32::from_le_bytes(d[44..48].try_into().unwrap());
        {
            let base = rd_u32(&d[..], 48) as usize;
            let n = rd_u32(&d[..], 52) as usize;
            for i in 0..n {
                let s = unsafe { core::slice::from_raw_parts((base + i * 52) as *const u8, 52) };
                v.overlay_layers.push(GhostShimmerOverlayData::decode_at(&s[0..]));
            }
        }
        {
            let base = rd_u32(&d[..], 56) as usize;
            let n = rd_u32(&d[..], 60) as usize;
            for i in 0..n {
                let s = unsafe { core::slice::from_raw_parts((base + i * 16) as *const u8, 16) };
                v.distortion_layers.push(GhostShimmerDistortionData::decode_at(&s[0..]));
            }
        }
        v
    }

    /// Renders this as the tier-2 table the engine expects, so a
    /// union-typed field can be filled from the typed struct instead of
    /// from hand-written key strings. An absent optional is omitted.
    pub fn to_value(&self) -> Value {
        let mut kv: Vec<(Value, Value)> = Vec::with_capacity(8);
        kv.push((Value::Str(LuaStr::from("tint")), self.tint.to_value()));
        kv.push((Value::Str(LuaStr::from("distortion")), Value::Number(self.distortion as f64)));
        kv.push((Value::Str(LuaStr::from("blend_mode")), Value::Number(self.blend_mode as f64)));
        kv.push((Value::Str(LuaStr::from("visualize_borders")), Value::Bool(self.visualize_borders)));
        kv.push((Value::Str(LuaStr::from("proportional_distortion")), Value::Bool(self.proportional_distortion)));
        kv.push((Value::Str(LuaStr::from("world_uv_modulo")), Value::Number(self.world_uv_modulo as f64)));
        if !self.overlay_layers.is_empty() {
            let mut a: Vec<Value> = Vec::with_capacity(self.overlay_layers.len());
            for e in self.overlay_layers.iter() {
                a.push(e.to_value());
            }
            kv.push((Value::Str(LuaStr::from("overlay_layers")), Value::Array(a)));
        }
        if !self.distortion_layers.is_empty() {
            let mut a: Vec<Value> = Vec::with_capacity(self.distortion_layers.len());
            for e in self.distortion_layers.iter() {
                a.push(e.to_value());
            }
            kv.push((Value::Str(LuaStr::from("distortion_layers")), Value::Array(a)));
        }
        Value::Map(kv)
    }
}

