        v.surface_index = u32::from_le_bytes(d[56..60].try_into().unwrap());
        if d[60] != 0 {
            v.unit_number = Some(u32::from_le_bytes(d[64..68].try_into().unwrap()));
        }
        v.name = u32::from_le_bytes(d[68..72].try_into().unwrap());
