pub struct OnPreChunkDeleted {
    pub surface_index: u32,
    pub positions: Vec<ChunkPosition>,
    pub name: u32,
    pub tick: u64,
}

impl OnPreChunkDeleted {
    pub fn encode_at(&self, d: &mut [u8]) {
        for b in d[..24].iter_mut() { *b = 0; }
        d[0..4].copy_from_slice(&(self.surface_index as u32).to_le_bytes());
        let p = galloc((self.positions.len() * 8) as u32);
        for (i, e) in self.positions.iter().enumerate() {
            let s = unsafe { core::slice::from_raw_parts_mut((p as usize + i * 8) as *mut u8, 8) };
            e.encode_at(&mut s[0..]);
        }
        wr_u32(&mut d[..], 4, p);
        wr_u32(&mut d[..], 8, self.positions.len() as u32);
        d[12..16].copy_from_slice(&(self.name as u32).to_le_bytes());
        d[16..24].copy_from_slice(&(self.tick).to_le_bytes());
    }

    pub fn decode_at(d: &[u8]) -> Self {
        let mut v = Self::default();
        v.surface_index = u32::from_le_bytes(d[0..4].try_into().unwrap());
        {
            let base = rd_u32(&d[..], 4) as usize;
            let n = rd_u32(&d[..], 8) as usize;
            for i in 0..n {
                let s = unsafe { core::slice::from_raw_parts((base + i * 8) as *const u8, 8) };
                v.positions.push(ChunkPosition::decode_at(&s[0..]));
            }
        }
        v.name = u32::from_le_bytes(d[12..16].try_into().unwrap());
        v.tick = u64::from_le_bytes(d[16..24].try_into().unwrap());
        v
    }

    /// Renders this as the tier-2 table the engine expects, so a
    /// union-typed field can be filled from the typed struct instead of
    /// from hand-written key strings. An absent optional is omitted.
    pub fn to_value(&self) -> Value {
        let mut kv: Vec<(Value, Value)> = Vec::with_capacity(4);
        kv.push((Value::Str(LuaStr::from("surface_index")), Value::Number(self.surface_index as f64)));
        if !self.positions.is_empty() {
            let mut a: Vec<Value> = Vec::with_capacity(self.positions.len());
            for e in self.positions.iter() {
                a.push(e.to_value());
            }
            kv.push((Value::Str(LuaStr::from("positions")), Value::Array(a)));
        }
        kv.push((Value::Str(LuaStr::from("name")), Value::Number(self.name as f64)));
        kv.push((Value::Str(LuaStr::from("tick")), Value::Number(self.tick as f64)));
        Value::Map(kv)
    }
}

